/**
 * Unit tests for StdDateFormat.parseAsISO8601.
 * Since the method is protected, we use reflection to access it.
 */
public class StdDateFormat_parseAsISO8601_TriageGen2Test {

    private StdDateFormat dateFormat;
    private Method parseAsISO8601Method;

    @Before
    public void setUp() throws Exception {
        dateFormat = new StdDateFormat();
        parseAsISO8601Method = StdDateFormat.class.getDeclaredMethod(
                "parseAsISO8601", String.class, ParsePosition.class, boolean.class);
        parseAsISO8601Method.setAccessible(true);
    }

    private Date invokeParseAsISO8601(String dateStr, ParsePosition pos, boolean throwErrors) throws Exception {
        return (Date) parseAsISO8601Method.invoke(dateFormat, dateStr, pos, throwErrors);
    }

    @Test
    public void testParsePlainDate() throws Exception {
        // len <= 10 and ends with digit
        Date result = invokeParseAsISO8601("2023-10-27", new ParsePosition(0), true);
        Calendar cal = Calendar.getInstance();
        cal.setTime(result);
        assertEquals(2023, cal.get(Calendar.YEAR));
        assertEquals(Calendar.OCTOBER, cal.get(Calendar.MONTH));
        assertEquals(27, cal.get(Calendar.DAY_OF_MONTH));
    }




















}

