        // case 8: sb.insert(offset, ".000")
        invokeParseAsISO8601("2023-10-27T10:00+0500", new ParsePosition(0), true);

        // case 6: sb.insert(offset, "00.000")
        invokeParseAsISO8601("2023-10-27T10+0500", new ParsePosition(0), true);

        // case 5: sb.insert(offset, ":00.000")
        invokeParseAsISO8601("2023-10-27T10+0500", new ParsePosition(0), true);
    }










}

